	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		w := w1
		if i == 0 { w = w0 }
		if i >= 2 { w = ws.weights[i] }
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 { s = 0 }
			if s > 1 { s = 1 }
			scores[snap.ID] += s * w
		}
