		// Shift weight heavily toward load-balance
		if inputLen < 64 {
			prefixW = 0.1
			loadW = 0.9
		} else if inputLen < 256 {
			// Medium inputs: moderate prefix benefit
			prefixW = 0.3
			loadW = 0.7
		} else {
			// Long inputs: prefix caching is very valuable
			prefixW = 0.6
			loadW = 0.4
		}

		// SLO-based adjustment: realtime requests are latency-sensitive
		if req.SLOClass == "realtime" {
			prefixW *= 0.5
			loadW *= 1.5
		} else if req.SLOClass == "batch" {
			prefixW *= 1.3
			loadW *= 0.8
		}

