	// Part 1: Relative load penalty (prevents imbalance)
	// Part 2: Absolute load penalty (prevents sending to overloaded instances)
	minLoad := snapshots[0].EffectiveLoad()
	maxLoad := snapshots[0].EffectiveLoad()
	totalLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
		if el > maxLoad {
			maxLoad = el
		}
		totalLoad += el
	}
